    total = sum(row.count(val) for row in grid)
    if total == 0:
        return False

    start = None
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == val:
                start = (r, c)
                break
        if start:
            break

    visited = set()
    queue = deque([start])
    visited.add(start)

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == val and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

    return len(visited) == total

